pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: caller will attempt to call transferOwnership and newOwner is target
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses in wide admissible domain but avoid zero-address for newOwner because function requires non-zero
        vm.assume(newOwner != address(0));

        // initialize contract so deployer (this) becomes owner
        c.initialize();

        // ensure caller has some ether so we can prank if needed (not strictly required but harmless)
        vm.deal(caller, 1 ether);

        bool ok;
        // attempt transferOwnership as `caller` and capture whether it succeeded
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: If caller was the current owner (address(this) right after initialize()),
        // then reference should allow the call to succeed and owner()==newOwner after call.
        // Concretely, for the reference contract the caller equals owner iff caller == address(this).
        // So the invariant: if caller == address(this) then transferOwnership must succeed and owner()==newOwner.
        // The mutant inverts onlyOwner, so when caller == address(this) the call will REVERT under the mutant,
        // causing this assertion to fail for those inputs.
        if (caller == address(this)) {
            // require that transfer succeeded and owner updated
            assertTrue(ok && c.owner() == newOwner);
        } else {
            // when caller is not the owner, both behaviors may differ across implementations; we do not assert here
            assertTrue(true);
        }
    }
}

