pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = address(0xABCD);

    function setUp() public {
        c = new C();
        // initialize and make owner be our chosen owner via initializer
        vm.prank(owner);
        c.initialize();
    }

    // Fuzzed parameter: the candidate newRoundImplementation address
    function testFuzz_property(address newImpl) public {
        // keep domain wide; no tight assumes so fuzzer can find address(0)
        // act as the owner to be able to call updateRoundImplementation
        vm.prank(owner);
        bool ok;
        try c.updateRoundImplementation(payable(newImpl)) {
            ok = true;
        } catch {
            ok = false;
        }

        // EXACTLY ONE assertion: for the correct contract, an owner call with newImpl == address(0)
        // must revert (so ok==false) and therefore roundImplementation must NOT be address(0).
        // For all other newImpl values that succeed, the stored value equals newImpl.
        // We express a single universal check that the contract does not accept and store address(0)
        // after an owner call: either the call reverted, or if it returned, the getter is non-zero.
        // This property holds for the reference (it reverts when newImpl==address(0)),
        // but fails for the mutant which will accept and set address(0).

        // Read the stored value from the contract
        address stored = c.roundImplementation();

        // Assert the invariant: it's impossible that the owner call succeeded (ok==true) and the stored value is address(0).
        // The reference satisfies this for all inputs; the mutant will fail when newImpl==address(0).
        assertTrue(!(ok && stored == address(0)));
    }
}

