pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address ownerAddr = address(0xBEEF);

    function setUp() public { c = new C(); }

    // Fuzzed params: caller (who we will make the owner) and newImpl to set
    function testFuzz_property(address caller, address newImpl) public {
        // keep domain wide but ensure caller is not zero to allow vm.prank
        vm.assume(caller != address(0));

        // make `caller` the owner by initializing and transferring ownership from default deployer
        // initialize must be called by any account; initialize sets _owner to msg.sender
        vm.prank(caller);
        c.initialize();

        // now caller is owner; call updateRoundImplementation as caller with newImpl
        bool ok;
        vm.prank(caller);
        try c.updateRoundImplementation(payable(newImpl)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for the correct contract, if newImpl == address(0) the call MUST revert (ok==false),
        // so roundImplementation can never become address(0) via owner call with zero; the mutant allows ok==true and sets it.
        // We assert that either the call reverted (ok==false) OR, if it did not revert, then roundImplementation != address(0).
        // This single assertion holds for the reference for ALL inputs and is violated by the mutant when caller is owner and newImpl==address(0).
        address stored = c.roundImplementation();
        assertTrue(!ok || stored != address(0));
    }
}

